def rect(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20): return '<rect x="%d" y="%d" width="%d" height="%d" rx="8" fill="%s" stroke="%s" stroke-width="3"/><text x="%d" y="%d" text-anchor="middle" font-size="%d" font-weight="800" fill="#0B2545" font-family="sans-serif">%s</text>'%(x,y,w,h,f,s,x+w//2,y+h//2+7,fs,t)
def dia(x,y,w,h,t,fs=20): return '<polygon points="%d,%d %d,%d %d,%d %d,%d" fill="#FFF9C4" stroke="#F9A825" stroke-width="3"/><text x="%d" y="%d" text-anchor="middle" font-size="%d" font-weight="800" fill="#0B2545" font-family="sans-serif">%s</text>'%(x+w//2,y,x+w,y+h//2,x+w//2,y+h,x,y+h//2,x+w//2,y+h//2+7,fs,t)
def ln(x1,y1,x2,y2,t='',tx=0,ty=0): return '<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="#0B2545" stroke-width="3" marker-end="url(#a)"/>'%(x1,y1,x2,y2)+('<text x="%d" y="%d" font-size="20" font-weight="800" fill="#D84315" font-family="sans-serif">%s</text>'%(tx,ty,t) if t else '')
