S.append(S2(c,B+' · 3','Bài mẫu 2: phương trình bậc hai',card('Phân tích',P('Với a ≠ 0, tính <b>Δ = b² − 4ac</b>.','<b>Δ &lt; 0</b>: vô nghiệm; <b>Δ = 0</b>: nghiệm kép x = −b/(2a); <b>Δ &gt; 0</b>: hai nghiệm x = (−b ± √Δ)/(2a).','Cần <b>import math</b> để dùng <code>math.sqrt</code>.','Tính tay x² − 5x + 6 = 0: Δ = 1 → x = 3 và 2.')),CODE('import math\na, b, c = map(float, input().split())\nd = b * b - 4 * a * c\nif d < 0:\n    print("Vo nghiem")\nelif d == 0:\n    print("Nghiem kep", -b / (2 * a))\nelse:\n    r = math.sqrt(d)\n    print((-b + r) / (2 * a), (-b - r) / (2 * a))',20)+R('import math\na, b, c = map(float, input().split())\nd = b * b - 4 * a * c\nif d < 0:\n    print("Vo nghiem")\nelif d == 0:\n    print("Nghiem kep", -b / (2 * a))\nelse:\n    r = math.sqrt(d)\n    print((-b + r) / (2 * a), (-b - r) / (2 * a))','1 -5 6\n',20,'Kết quả (1 −5 6)')))
