S.append(S2(c,B+' · 3','Bài mẫu 5: số ngày trong tháng',card('Phân tích',P('Tháng <b>1, 3, 5, 7, 8, 10, 12</b>: 31 ngày. Tháng <b>4, 6, 9, 11</b>: 30 ngày.','Tháng <b>2</b>: 29 ngày nếu năm nhuận, ngược lại 28.','<b>Năm nhuận</b>: chia hết cho 400, hoặc chia hết cho 4 mà không chia hết cho 100. Ví dụ 2000, 2024 nhuận; 1900, 2023 không nhuận.')),CODE('t, n = map(int, input().split())\nif t in (1, 3, 5, 7, 8, 10, 12):\n    print(31)\nelif t in (4, 6, 9, 11):\n    print(30)\nelif n % 400 == 0 or (n % 4 == 0 and n % 100 != 0):\n    print(29)\nelse:\n    print(28)',19)+R('t, n = map(int, input().split())\nif t in (1, 3, 5, 7, 8, 10, 12):\n    print(31)\nelif t in (4, 6, 9, 11):\n    print(30)\nelif n % 400 == 0 or (n % 4 == 0 and n % 100 != 0):\n    print(29)\nelse:\n    print(28)','2 1900\n',22,'Kết quả (tháng 2, năm 1900)')+KEY('<code>t in (1, 3, 5)</code> kiểm tra t có <b>nằm trong tập</b> các giá trị: gọn hơn nhiều chữ <b>or</b>.')))
S.append(S2(c,B+' · 3','Bài mẫu 6: tìm số lớn nhất, nhỏ nhất của ba số',card('Hai cách',P('<b>Cách 1</b>: dùng hàm <code>max</code>, <code>min</code>.','<b>Cách 2</b>: so sánh bằng if (kĩ năng cơ bản): giả sử a lớn nhất, rồi so sánh với b, c.')),CODE('a, b, c = map(int, input().split())\nlon = a\nif b > lon:\n    lon = b\nif c > lon:\n    lon = c\nprint(lon, max(a, b, c))',22)+R('a, b, c = map(int, input().split())\nlon = a\nif b > lon:\n    lon = b\nif c > lon:\n    lon = c\nprint(lon, max(a, b, c))','4 9 7\n',24,'Kết quả (4 9 7)')+KEY('Dùng <b>hai if rời nhau</b> (không elif) vì mỗi số đều phải được so với giá trị lớn nhất hiện tại.')))
# 4 Lỗi
S.append(TB(c,B+' · 4','Lỗi thường gặp với rẽ nhánh',['Lỗi','Ví dụ sai','Cách sửa'],[['Dùng <b>=</b> thay <b>==</b>','<code>if x = 5:</code> (SyntaxError)','<code>if x == 5:</code>'],['Thiếu dấu <b>:</b>','<code>if x &gt; 0</code>','<code>if x &gt; 0:</code>'],['Sai thụt lề','lệnh của if không thụt vào','thụt 4 dấu cách'],['So sánh xâu với số','<code>x = input(); if x &gt; 5</code> (TypeError)','<code>if int(x) &gt; 5</code>'],['<code>x == 3 or 5</code>','luôn đúng','<code>x == 3 or x == 5</code> hoặc <code>x in (3, 5)</code>'],['Sai thứ tự elif','điều kiện rộng đặt trước','đặt điều kiện hẹp trước']],note=KEY('Chạy thử <b>mọi nhánh</b>: mỗi nhánh một bộ dữ liệu, kể cả các giá trị <b>biên</b> (bằng đúng mốc).')))
S.append(SELF(c,B+' · 4','Tự kiểm tra: if – if và if – elif','Chương trình in ra gì với x = 6? Với x = 12?','x = int(input())\nif x % 2 == 0:\n    print("A")\nif x % 3 == 0:\n    print("B")\nelif x % 4 == 0:\n    print("C")\nelse:\n    print("D")',P('<b>x = 6</b>: <b>if</b> đầu: 6 chẵn → in <b>A</b>. Cặp <b>if–elif–else</b> thứ hai: 6 % 3 == 0 → in <b>B</b> (bỏ qua elif, else). Kết quả: <b>A B</b>.','<b>x = 12</b>: A (12 chẵn). 12 % 3 == 0 → B. Dù 12 cũng chia hết cho 4, nhánh <b>elif không được xét</b>. Kết quả: <b>A B</b>.')+R('x = 12\nif x % 2 == 0:\n    print("A")\nif x % 3 == 0:\n    print("B")\nelif x % 4 == 0:\n    print("C")\nelse:\n    print("D")','',22,'Chạy với x = 12'),19))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): thứ tự điều kiện và biên','Với điểm d = 8, 6.5, 5, 4.99, hãy cho biết xếp loại của chương trình sau. Có chỗ nào chương trình bỏ sót không?','if d > 8:\n    print("Gioi")\nelif d > 6.5:\n    print("Kha")\nelif d >= 5:\n    print("TB")\nelse:\n    print("Yeu")',P('<b>d = 8</b>: 8 &gt; 8 sai; 8 &gt; 6.5 đúng → <b>Kha</b> (đáng lẽ là Giỏi nếu quy định ≥ 8).','<b>d = 6.5</b>: 6.5 &gt; 6.5 sai; 6.5 ≥ 5 đúng → <b>TB</b> (đáng lẽ Khá).','<b>d = 5</b> → TB; <b>d = 4.99</b> → Yeu.')+KEY('Lỗi ở các điểm <b>biên</b>: dùng <b>&gt;</b> thay vì <b>&gt;=</b>. Luôn thử đúng các mốc 8, 6.5, 5.')+R('for d in (8, 6.5, 5, 4.99):\n    if d > 8:\n        print(d, "Gioi")\n    elif d > 6.5:\n        print(d, "Kha")\n    elif d >= 5:\n        print(d, "TB")\n    else:\n        print(d, "Yeu")','',22,'Kết quả thật'),19))
S+=END(c,B,['<b>if</b> làm khi đúng; <b>if-else</b> chọn một trong hai; <b>if-elif-else</b> chọn <b>một</b> trong nhiều.','Thụt lề 4 dấu cách và dấu <b>:</b> là bắt buộc.','Gặp điều kiện <b>đúng đầu tiên</b> thì thoát: <b>thứ tự</b> các điều kiện rất quan trọng.','<b>if – if</b> xét độc lập; <b>if – elif</b> tối đa một nhánh.','Điều kiện phức: and, or, not; <code>a &lt;= x &lt;= b</code>; <code>x in (…)</code>.','<code>a if đk else b</code> chọn giá trị gọn.'],[('Cuối dòng if','dấu :'),('Một trong nhiều','elif'),('x == 3 or x == 5','x in (3, 5)'),('Chọn giá trị','a if đk else b')],'Nhầm <b>=</b> với <b>==</b>; sai thứ tự elif; sai ở giá trị <b>biên</b>.',['<code>x == 3 or 5</code> luôn đúng.','Giá trị biên: &gt; khác &gt;=.','<b>else</b> thuộc về <b>if gần nhất</b> cùng mức thụt lề.','Sắp xếp ba cạnh trước khi xét tam giác vuông.'],['<b>match – case</b> (Python 3.10) cho nhiều giá trị.','<b>Bảng quyết định</b> thay chuỗi elif dài.','Toán tử <b>:=</b> (walrus) trong điều kiện.'],
 [('Viết điều kiện: x là số chẵn có hai chữ số.',),('<code>print("A" if 7 > 5 else "B")</code> in gì?',),('Với <code>x = 0</code>, <code>if x:</code> chạy nhánh nào?',),('Điều kiện kiểm tra n là bội của cả 4 và 6?',),('Năm 2100 có nhuận không?',)],
 [('<code>10 &lt;= x &lt;= 99 and x % 2 == 0</code> (hoặc <code>abs(x)</code> nếu cho số âm).',),('<b>A</b>.',),('Nhánh <b>else</b> (0 là giả).',),('<code>n % 12 == 0</code> (bội chung nhỏ nhất của 4 và 6 là 12).',),('<b>Không</b>: chia hết cho 100 mà không chia hết cho 400.',)],
 [('Mức 1. Nhập số nguyên n. In “Duong”, “Am” hoặc “Khong”. Thử n = −3.',),('Mức 1. Nhập ba số a, b, c. In số <b>ở giữa</b> (trung vị) mà không dùng sort. Thử 5 9 7.',),('Mức 2. Nhập thu nhập. Thuế: ≤ 10 triệu: 5%; phần từ 10 đến 30 triệu: 10%; phần trên 30 triệu: 20%. Tính thuế cho 45 triệu.',),('Mức 2. Nhập ngày, tháng, năm. Cho biết ngày đó <b>có hợp lệ</b> không (kể cả năm nhuận). Thử 29 2 2023 và 29 2 2024.',),('Mức 3 (HSG). Nhập giờ h, phút m. Tính góc nhỏ (độ) giữa kim giờ và kim phút. Thử 3 00, 12 30, 6 15.',),('Mức 3 (HSG). Nhập 4 số. In YES nếu <b>có thể</b> chọn ba số làm độ dài ba cạnh một tam giác vuông. Thử 3 4 5 9 và 5 12 13 14 và 2 3 4 5.',)],
 [(RUN('n=-3\nprint("Duong" if n>0 else "Am" if n<0 else "Khong")')+' (biểu thức điều kiện lồng nhau).',),('Sắp xếp rồi lấy giữa là cách gọn; nếu không dùng sort: <code>a + b + c - max(a,b,c) - min(a,b,c)</code> = '+RUN('a,b,c=5,9,7\nprint(a+b+c-max(a,b,c)-min(a,b,c))')+'.',),('Thuế = 10×5% + 20×10% + 15×20% = 0,5 + 2 + 3 = <b>5,5 triệu</b>. Kiểm: '+RUN('t=45\nprint(min(t,10)*0.05+max(0,min(t,30)-10)*0.1+max(0,t-30)*0.2)')+'.',),('Hợp lệ khi 1 ≤ tháng ≤ 12 và 1 ≤ ngày ≤ số ngày trong tháng. 29/2/2023: 2023 không nhuận → <b>không hợp lệ</b>; 29/2/2024: hợp lệ.',),('Góc kim giờ = (h % 12) × 30 + m × 0,5; góc kim phút = m × 6; góc = |hiệu|, rồi lấy <code>min(g, 360 − g)</code>. 3:00 → '+RUN('h,m=3,0\ng=abs((h%12)*30+m*0.5-m*6)\nprint(min(g,360-g))')+'; 12:30 → '+RUN('h,m=12,30\ng=abs((h%12)*30+m*0.5-m*6)\nprint(min(g,360-g))')+'; 6:15 → '+RUN('h,m=6,15\ng=abs((h%12)*30+m*0.5-m*6)\nprint(min(g,360-g))')+'.',),('Thử từng bộ ba (có 4 bộ), sắp xếp rồi kiểm tra a² + b² = c². 3 4 5 9 → YES (3,4,5); 5 12 13 14 → YES; 2 3 4 5 → NO (kiểm: '+RUN('from itertools import combinations\nfor q in ((3,4,5,9),(5,12,13,14),(2,3,4,5)):\n    print("YES" if any(sorted(t)[0]**2+sorted(t)[1]**2==sorted(t)[2]**2 for t in combinations(q,3)) else "NO", end=" ")')+').',)],hper=2)
